-- READ ONLY. Inspect the already-applied production post-001B checkpoint; do not rerun 001A, containment or 001B.
-- 1. Exact structural inventory.
select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) table_count,(select count(*) from pg_constraint c where c.conrelid=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']::regclass[])) constraint_count,(select count(*) from pg_indexes where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) index_count;
-- 2. RLS, policies, triggers and exact effective table privileges.
select c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1;
select tablename,policyname,roles,cmd,qual,with_check from pg_policies where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
select t.name table_name,r.name role_name,p.name privilege,has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name) effective from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) cross join (values(0::oid,'PUBLIC'),('anon'::regrole::oid,'anon'),('authenticated'::regrole::oid,'authenticated'),('service_role'::regrole::oid,'service_role')) r(oid,name) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) order by 1,2,3;
select event_object_table,trigger_name,action_timing,event_manipulation from information_schema.triggers where event_object_schema='public' and event_object_table=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
-- 3. Functions expected at the checkpoint. Lifecycle functions must still be absent.
select to_regprocedure('public.openingfit_protect_mission_identity()') identity_protection,to_regprocedure('public.transition_openingfit_mission(uuid,uuid,text,text,text,text,jsonb)') transition_function,to_regprocedure('public.dismiss_openingfit_mission(uuid,text,text)') dismissal_function;
-- 4. Exact classification. Expected: post_001b_complete.
select case when (select count(*) from pg_class r join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relkind='r' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']))=4 and not exists(select 1 from (values ('openingfit_missions','openingfit_missions_one_primary_active_idx',$idx$CREATE UNIQUE INDEX openingfit_missions_one_primary_active_idx ON public.openingfit_missions USING btree (user_id) WHERE (is_primary AND (status = ANY (ARRAY['assigned'::text, 'learning'::text, 'awaiting_evidence'::text, 'improving'::text, 'needs_review'::text])))$idx$), ('openingfit_missions','openingfit_missions_current_lookup_idx',$idx$CREATE INDEX openingfit_missions_current_lookup_idx ON public.openingfit_missions USING btree (user_id, status, updated_at DESC) WHERE is_primary$idx$), ('openingfit_missions','openingfit_missions_history_idx',$idx$CREATE INDEX openingfit_missions_history_idx ON public.openingfit_missions USING btree (user_id, created_at DESC)$idx$), ('openingfit_missions','openingfit_missions_position_idx',$idx$CREATE INDEX openingfit_missions_position_idx ON public.openingfit_missions USING btree (user_id, exact_position_key, status)$idx$), ('openingfit_missions','openingfit_missions_source_report_idx',$idx$CREATE INDEX openingfit_missions_source_report_idx ON public.openingfit_missions USING btree (user_id, source_report_id) WHERE (source_report_id IS NOT NULL)$idx$), ('openingfit_mission_training_attempts','openingfit_mission_attempts_history_idx',$idx$CREATE INDEX openingfit_mission_attempts_history_idx ON public.openingfit_mission_training_attempts USING btree (user_id, mission_id, created_at DESC)$idx$), ('openingfit_mission_encounters','openingfit_mission_encounters_verification_idx',$idx$CREATE INDEX openingfit_mission_encounters_verification_idx ON public.openingfit_mission_encounters USING btree (user_id, mission_id, qualifies_for_verification, played_at)$idx$), ('openingfit_mission_status_events','openingfit_mission_status_events_history_idx',$idx$CREATE INDEX openingfit_mission_status_events_history_idx ON public.openingfit_mission_status_events USING btree (user_id, mission_id, created_at)$idx$)) e(tablename,indexname,indexdef) left join pg_indexes a on a.schemaname='public' and a.indexname=e.indexname where a.tablename is distinct from e.tablename or a.indexdef is distinct from e.indexdef) and (select count(*)=46 and md5(string_agg(n.nspname||'.'||r.relname||'|'||c.conname||'|'||c.contype::text||'|'||pg_get_constraintdef(c.oid,false),chr(10) order by n.nspname,r.relname,c.conname))='cb93fc8e4263fd7b74d89d8fc1527d02' from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) and (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) and c.relrowsecurity)=4 and (select count(*) from pg_policies where schemaname='public' and policyname like 'openingfit_mission%select_own')=4 and exists(select 1 from pg_trigger where tgrelid=to_regclass('public.openingfit_missions') and tgname='openingfit_protect_mission_identity' and not tgisinternal) and not exists(select 1 from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) cross join (values(0::oid,'public'),('anon'::regrole::oid,'anon'),('authenticated'::regrole::oid,'authenticated'),('service_role'::regrole::oid,'service_role')) r(oid,name) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) where has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name) is distinct from (case when r.name='authenticated' then p.name='SELECT' when r.name='service_role' then p.name in ('SELECT','INSERT') or (t.name='openingfit_missions' and p.name='UPDATE') else false end)) and to_regprocedure('public.transition_openingfit_mission(uuid,uuid,text,text,text,text,jsonb)') is null and to_regprocedure('public.dismiss_openingfit_mission(uuid,text,text)') is null then 'post_001b_complete' else 'checkpoint_mismatch' end classification;
